{
  "pass": false,
  "problems": [
    {
      "type": "中身のずれ",
      "where": "summary の hs",
      "detail": "std にある「指名は他のすべての案件に先立って行われます」という重要な情報が、hs から抜けています。",
      "fix": "「内閣総理大臣は、国会議員の中から国会が選び、天皇が任命します。指名は他のすべての案件に先立って行われます。」のように情報を補ってください。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/0/text の hs",
      "detail": "std の文（総選挙のあと、内閣総理大臣が決まるまで、国の仕事はどうなっている？）とは全く異なる質問（総理大臣は国民の投票で直接選ばれているのでしょうか？）になっており、中身が完全にずれています。",
      "fix": "std の意味に沿って「総選挙のあと、内閣総理大臣が決まるまで、国の仕事はどうなるのでしょうか。」のように直してください。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/1/items/0/text の hs",
      "detail": "std の後半にある「指名は他のすべての案件に先立って行われます（第67条第1項）。」の情報が hs から抜けています。",
      "fix": "「衆議院と参議院が、それぞれ本会議で投票して総理大臣にする人を決めます。この指名は、ほかのすべてのことより先に行われます。」のように直してください。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/1/items/3/text の hs",
      "detail": "std にある「天皇がその任免を認証します（第7条第5号）」の情報が hs から抜けています。",
      "fix": "「総理大臣が国務大臣を選び、天皇がそれを認証します。」のように直してください。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/3/text の hs",
      "detail": "std の「指名は国会の議決で行われるため、議院内閣制のもとでは国会の多数の支持を得た者が指名されます」という内容に対し、hs では「ほとんどの場合、国会で多くの議席を持つ政党や会派の代表が選ばれてきました」と追加の解説や表現のずれが生じています。",
      "fix": "std の内容に合わせて「総理大臣は国会議員でなければなりません。国会で多くの賛成を得た人が選ばれます。」のように修正してください。"
    }
  ]
}
